// ─────────────────────────────────────────────────────────────────
// Driver
// ─────────────────────────────────────────────────────────────────
async function genFor(framework) {
  const proj = `feat-${framework.replace(/[^a-z0-9]/g, '-')}-${Date.now()}`;
  console.log(`\n══ Framework: ${framework}  (project: ${proj}) ══`);

  const c1 = await api('POST', '/api/projects',
    { name: proj, framework, baseUrl: 'https://demoqa.com' });
  chk(`create project (${c1.status})`, c1.status === 200 || c1.status === 201);

  const c2 = await api('POST', `/api/projects/${proj}/save`, {
    framework, baseUrl: 'https://demoqa.com',
    steps: STEPS, locators: LOCATORS,
    scenarios: SCENARIOS, backgroundSteps: BACKGROUND_STEPS,
  });
  chk(`save kitchen-sink (${c2.status} — ${STEPS.length} steps, ${LOCATORS.length} locators, ${SCENARIOS.length} scenarios)`,
    c2.status === 200 || c2.status === 201);

  const c3 = await api('POST', `/api/projects/${proj}/generate-files`, {
    framework, featureName: 'Recorded', featureTitle: `KitchenSink-${framework}`,
    baseUrl: 'https://demoqa.com', tags: ['@kitchen-sink','@regression'],
  }, 120000);
  chk(`generate-files (${c3.status} — ${(c3.body && c3.body.count) || 0} files)`,
    c3.status === 200 && c3.body && c3.body.success !== false,
    JSON.stringify(c3.body).slice(0, 200));

  if (c3.status !== 200) return proj;

  // Locate every generated source file we care about
  const projDir = join(ROOT, 'projects', proj);
  const matrix  = MATRIX[framework];
  if (!matrix) {
    chk(`unknown framework "${framework}" in matrix`, false);
    return proj;
  }

  // Find all step-def / test files for this framework's glob
  const files = collect(projDir, matrix.glob);
  chk(`step/test source files emitted (${files.length} found, glob=${matrix.glob})`,
    files.length >= 1, `under ${projDir}`);
  if (files.length === 0) return proj;

  const txt = files.map(f => readFileSync(f, 'utf8')).join('\n────\n');

  for (const [label, expect] of matrix.expectations) {
    let ok;
    if (typeof expect === 'function') {
      ok = expect(txt);
    } else if (Array.isArray(expect)) {
      ok = expect.some(re => re.test(txt));
    } else {
      ok = expect.test(txt);
    }
    chk(`  ${label}`, ok, label);
  }

  // ─── Feature file: Background + 3 scenarios + Examples ───
  // selenium-testng is pure-TestNG (no Cucumber), so no .feature is
  // expected for it; skip the feature checks in that case.
  const featureFiles = collect(projDir, '**/*.feature');
  if (framework === 'selenium-testng') {
    chk(`feature file: not expected for pure TestNG (got ${featureFiles.length}, ok if 0)`, true);
  } else {
    chk(`feature file emitted (${featureFiles.length})`, featureFiles.length >= 1);
  }
  if (featureFiles.length > 0) {
    const f = readFileSync(featureFiles[0], 'utf8');
    chk('  feature: Feature: keyword', /^Feature:/m.test(f));
    chk('  feature: Background block', /^\s+Background:/m.test(f));
    chk('  feature: ≥3 Scenario blocks',
      ((f.match(/^\s+Scenario(?:\s|:)/gm) || []).length) >= 3,
      `found ${(f.match(/^\s+Scenario(?:\s|:)/gm) || []).length}`);
    chk('  feature: Scenario Outline + Examples', /Scenario Outline:/.test(f) && /Examples:/.test(f));
    chk('  feature: tags rendered',  /@kitchen-sink|@positive|@negative|@data-driven/.test(f));
    chk('  feature: column-aware Outline placeholders (no orphan <value>)',
      !/"<value>"/.test(f),
      'should use <Username>/<Password> not <value>');
  }

  // ─── Page object generation (Java only — TS/JS don't generate POs in this branch) ───
  if (framework === 'selenium-java' || framework === 'playwright-java') {
    const pageFiles = collect(projDir, 'src/test/java/pages/*.java');
    chk(`  page objects emitted (${pageFiles.length})`,  pageFiles.length >= 1);
    if (pageFiles.length > 0) {
      const pageTxt = pageFiles.map(p => readFileSync(p, 'utf8')).join('\n');
      chk('  page object: at least one Java class',  /public class \w+Page/.test(pageTxt));
      // Locator strategies — id should produce By.id, css → By.cssSelector, xpath → By.xpath
      if (framework === 'selenium-java') {
        chk('  page object: id-strategy locator (id="userName" or @FindBy(id=...))',
          /id\s*=\s*"userName"|@FindBy\(id\s*=/i.test(pageTxt));
        chk('  page object: css-strategy locator (#submit)',
          pageTxt.includes('#submit'));
        chk('  page object: xpath-strategy locator (//div[@class=)',
          /xpath\s*=|By\.xpath\(/.test(pageTxt));
      } else {
        // playwright-java
        chk('  page object: locator() call', /\.locator\(/.test(pageTxt));
        chk('  page object: css selector preserved (#submit)', pageTxt.includes('#submit'));
      }
    }
  }

  // ─── Lifecycle / hooks ───
  if (framework === 'selenium-java') {
    const wt = read(join(projDir, 'src/test/java/support/SeleniumWorld.java')) || '';
    chk('  World: @Before / @After hooks',  /@Before\b/.test(wt) && /@After\b/.test(wt));
    chk('  World: WebDriver field',          /WebDriver\s+driver\b/.test(wt));
  } else if (framework === 'playwright-java') {
    const wt = read(join(projDir, 'src/test/java/support/PlaywrightWorld.java')) || '';
    chk('  World: @Before / @After hooks',  /@Before\b/.test(wt) && /@After\b/.test(wt));
    chk('  World: Playwright fields',        /Playwright\s+playwright|Browser\s+browser/.test(wt));
    chk('  World: screenshot-on-failure',    /scenario\.isFailed\(\)/.test(wt));
  } else if (framework === 'selenium-testng') {
    const tngTxt = collect(projDir, 'src/test/java/**/*Test.java').map(f => readFileSync(f, 'utf8')).join('\n');
    chk('  Test: @BeforeMethod / @AfterMethod', /@BeforeMethod\b/.test(tngTxt) && /@AfterMethod\b/.test(tngTxt));
    chk('  Test: WebDriver field',              /WebDriver\s+driver\b/.test(tngTxt));
  } else {
    const worldFile = framework === 'playwright-javascript' ? 'support/world.js' : 'support/world.ts';
    const wt = read(join(projDir, worldFile)) || '';
    chk(`  World: ${worldFile}: setWorldConstructor`, /setWorldConstructor/.test(wt));
    chk(`  World: ${worldFile}: init/cleanup methods`, /async init\b|async cleanup\b/.test(wt));
  }

  return proj;
}

function collect(root, pattern) {
  // Tiny no-deps glob using `find` (macOS / Linux). We only need to
  // resolve `*.java`, `**/*.java`, `support/world.ts` style patterns.
  if (!existsSync(root)) return [];
  const out = [];
  const isWildcard = pattern.includes('*');
  if (!isWildcard) {
    const p = join(root, pattern);
    if (existsSync(p)) out.push(p);
    return out;
  }
  // Use find for simplicity — patterns involve at most ** and one extension.
  const ext = pattern.split('.').pop();
  const subdir = pattern.split('/').slice(0, -1).filter(p => !p.includes('*')).join('/');
  const baseDir = subdir ? join(root, subdir) : root;
  if (!existsSync(baseDir)) return out;
  const result = spawnSync('find', [baseDir, '-name', `*.${ext}`], { encoding: 'utf8' });
  return (result.stdout || '').split('\n').filter(Boolean);
}

function read(p) {
  try { return readFileSync(p, 'utf8'); } catch { return null; }
}

(async () => {
  console.log(`══ Codegen feature regression — ${BASE} ══`);
  const created = [];
  for (const fw of Object.keys(MATRIX)) {
    const proj = await genFor(fw);
    if (proj) created.push(proj);
  }
  console.log('\n── Cleanup ──');
  for (const p of created) {
    await api('DELETE', `/api/projects/${p}`);
    spawnSync('rm', ['-rf', join(ROOT, 'projects', p)]);
  }
  console.log('\n═══ Summary ═══');
  console.log(`   Total: ${T.pass + T.fail}`);
  console.log(`   ✓ pass: ${T.pass}`);
  console.log(`   ✗ fail: ${T.fail}`);
  if (T.fail) {
    console.log('\n   Failures:');
    for (const f of T.fails) console.log(`     - ${f.label}${f.detail ? '  — ' + f.detail : ''}`);
  }
  process.exit(T.fail === 0 ? 0 : 1);
})().catch(e => { console.error(e); process.exit(2); });
